//! First-class adapters for external coding-agent runtimes.
//!
//! Provider-specific discovery, launch configuration, and event parsing live
//! here. Agent Host remains authoritative for permissions, authoring, and
//! completion.

use serde_json::{json, Value};
use std::ffi::{OsStr, OsString};
use std::io;
