#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum ExternalAgentProviderKind {
    ClaudeCode,
    Codex,
    Generic,
}

impl ExternalAgentProviderKind {
    pub(crate) const ALL: [Self; 3] = [Self::ClaudeCode, Self::Codex, Self::Generic];

    pub(crate) const fn label(self) -> &'static str {
        match self {
            Self::ClaudeCode => "Claude Code",
            Self::Codex => "Codex",
            Self::Generic => "Compatible process",
        }
    }

    pub(crate) const fn executable_name(self) -> Option<&'static str> {
        match self {
            Self::ClaudeCode => Some("claude"),
            Self::Codex => Some("codex"),
            Self::Generic => None,
        }
    }

    pub(crate) const fn capabilities(self) -> ExternalAgentProviderCapabilities {
        ExternalAgentProviderCapabilities {
            structured_events: !matches!(self, Self::Generic),
            ephemeral_mcp: !matches!(self, Self::Generic),
            cancellation: true,
            provider_managed_auth: !matches!(self, Self::Generic),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct ExternalAgentProviderCapabilities {
    pub(crate) structured_events: bool,
    pub(crate) ephemeral_mcp: bool,
    pub(crate) cancellation: bool,
    pub(crate) provider_managed_auth: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum ProviderAuthStatus {
    Authenticated,
    NotAuthenticated,
    ProviderDefined,
    Unknown,
}

impl ProviderAuthStatus {
    pub(crate) const fn label(self) -> &'static str {
        match self {
            Self::Authenticated => "authenticated",
            Self::NotAuthenticated => "not authenticated",
            Self::ProviderDefined => "provider-defined",
            Self::Unknown => "unknown",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct ExternalAgentProviderStatus {
    pub(crate) discovered: bool,
    pub(crate) auth: ProviderAuthStatus,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum ExternalAgentLaunchPurpose {
    BuildOrRepair,
    RuntimeEvaluation,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct ExternalAgentLaunchPlan {
    pub(crate) program: OsString,
    pub(crate) args: Vec<OsString>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct ExternalAgentProviderSelection {
    pub(crate) kind: ExternalAgentProviderKind,
    generic_program: String,
    additional_args: String,
}

impl ExternalAgentProviderSelection {
    pub(crate) fn new(
        kind: ExternalAgentProviderKind,
        generic_program: &str,
        additional_args: &str,
    ) -> Result<Self, String> {
        if kind == ExternalAgentProviderKind::Generic && generic_program.trim().is_empty() {
            return Err("Configure a compatible external agent program before Go.".to_owned());
        }
        Ok(Self {
            kind,
            generic_program: generic_program.trim().to_owned(),
            additional_args: additional_args.to_owned(),
        })
    }

    pub(crate) const fn provider_label(&self) -> &'static str {
        self.kind.label()
    }

    pub(crate) fn launch_plan(
        &self,
        endpoint: &str,
        purpose: ExternalAgentLaunchPurpose,
    ) -> Result<ExternalAgentLaunchPlan, String> {
        match self.kind {
            ExternalAgentProviderKind::ClaudeCode => {
                claude_plan(endpoint, &self.additional_args, purpose)
            }
            ExternalAgentProviderKind::Codex => {
                Ok(codex_plan(endpoint, &self.additional_args, purpose))
            }
            ExternalAgentProviderKind::Generic => Ok(ExternalAgentLaunchPlan {
                program: OsString::from(&self.generic_program),
                args: direct_args(&self.additional_args)
                    .into_iter()
                    .map(OsString::from)
                    .collect(),
            }),
        }
    }
}

